import { useState, type FormEvent } from "react";
import { useQuery, useQueryClient } from "@tanstack/react-query";
import { loadAdministration, updateProfile, updateUser, resetUserPassword } from "@/lib/admin";
import type { Profile, ManagedUser } from "@/lib/admin-model";
import { PageTitle, Panel, Table, Th, Td, Badge } from "./ui-kit";
const control = "rounded-md border border-line bg-white px-3 py-2 text-sm w-full";
const button = "rounded-md bg-brand px-3 py-2 text-sm font-medium text-white disabled:opacity-50";
const permissions = {
  manage_users: "Gerenciar usuários",
  manage_profiles: "Gerenciar perfis",
  view_audit: "Consultar auditoria",
  write_cash: "Alterar fluxo de caixa",
  manage_companies: "Gerenciar empresas",
  write_accounting: "Operar módulos contábeis",
  close_periods: "Gerenciar e encerrar períodos",
} as const;
export function AdministrationList({ kind }: { kind: "users" | "profiles" }) {
  const query = useQuery({ queryKey: ["administration"], queryFn: () => loadAdministration() });
  const client = useQueryClient();
  const [editing, setEditing] = useState<ManagedUser | Profile | "new" | null>(null);
  const [search, setSearch] = useState("");
  const [error, setError] = useState("");
  const [notice, setNotice] = useState("");
  const [pending, setPending] = useState(false);
  const [resetTarget, setResetTarget] = useState<ManagedUser | null>(null);
  const [generatedPassword, setGeneratedPassword] = useState("");
  const [copied, setCopied] = useState(false);
  async function resetPassword() {
    if (!resetTarget || pending) return;
    setPending(true);
    setError("");
    try {
      const result = await resetUserPassword({ data: { id: resetTarget.id } });
      setGeneratedPassword(result.password);
      setCopied(false);
    } catch (error) {
      setError(error instanceof Error ? error.message : "Não foi possível redefinir a senha.");
    } finally {
      setPending(false);
    }
  }
  async function copyPassword() {
    try {
      await navigator.clipboard.writeText(generatedPassword);
      setCopied(true);
      setError("");
    } catch {
      setError("Não foi possível copiar. Selecione a senha e copie manualmente.");
    }
  }
  const users = kind === "users";
  const allowed = users
    ? query.data?.permissions.manage_users
    : query.data?.permissions.manage_profiles;
  async function submit(e: FormEvent<HTMLFormElement>) {
    e.preventDefault();
    if (pending) return;
    const f = new FormData(e.currentTarget);
    setPending(true);
    setError("");
    setNotice("");
    try {
      const base = {
        ...(editing && editing !== "new" ? { id: editing.id } : {}),
        name: String(f.get("name")),
      };
      if (users)
        await updateUser({
          data: {
            ...base,
            email: String(f.get("email")),
            profile_id: String(f.get("profile_id")),
            active: f.get("active") === "on",
            ...(f.get("password") ? { password: String(f.get("password")) } : {}),
          },
        });
      else
        await updateProfile({
          data: {
            ...base,
            manage_users: f.get("manage_users") === "on",
            manage_profiles: f.get("manage_profiles") === "on",
            view_audit: f.get("view_audit") === "on",
            write_cash: f.get("write_cash") === "on",
            manage_companies: f.get("manage_companies") === "on",
            write_accounting: f.get("write_accounting") === "on",
            close_periods: f.get("close_periods") === "on",
            all_companies: f.get("all_companies") === "on",
            company_ids: f.getAll("company_ids").map(String),
          },
        });
      await client.invalidateQueries({ queryKey: ["administration"] });
      await client.invalidateQueries({ queryKey: ["companies"] });
      await client.invalidateQueries({ queryKey: ["accounting"] });
      setEditing(null);
      setNotice("Alterações salvas e registradas na auditoria.");
    } catch (e) {
      setError(e instanceof Error ? e.message : "Não foi possível salvar.");
    } finally {
      setPending(false);
    }
  }
  const rows =
    (users ? query.data?.users : query.data?.profiles)?.filter((r) =>
      `${r.name} ${"email" in r ? r.email : ""}`.toLowerCase().includes(search.toLowerCase()),
    ) ?? [];
  return (
    <div className="space-y-4">
      <PageTitle
        title={users ? "Configurações · Usuários" : "Configurações · Perfis de acesso"}
        description="Gerencie os acessos ao sistema em listas."
        actions={
          allowed ? (
            <button
              className={button}
              onClick={() => {
                setEditing("new");
                setError("");
                setNotice("");
              }}
            >
              {users ? "Novo usuário" : "Novo perfil"}
            </button>
          ) : undefined
        }
      />
      {query.isPending && <p role="status">Carregando…</p>}
      {query.isError && (
        <p role="alert">
          Não foi possível carregar. Verifique a conexão e a migração 003_access_audit.sql.{" "}
          <button onClick={() => void query.refetch()} className="underline">
            Tentar novamente
          </button>
        </p>
      )}
      {query.isSuccess && !allowed && (
        <p role="alert">Seu perfil não permite gerenciar esta lista.</p>
      )}
      {error && (
        <p role="alert" className="text-down">
          {error}
        </p>
      )}
      {notice && (
        <p role="status" className="text-up">
          {notice}
        </p>
      )}
      {allowed && (
        <>
          <input
            aria-label="Buscar na lista"
            placeholder="Buscar por nome ou e-mail…"
            className={control}
            value={search}
            onChange={(e) => setSearch(e.target.value)}
          />
          <Panel title={`${users ? "Usuários" : "Perfis de acesso"} (${rows.length})`}>
            <Table>
              <thead>
                <tr>
                  <Th>Nome</Th>
                  {users ? (
                    <>
                      <Th>E-mail</Th>
                      <Th>Perfil</Th>
                      <Th>Status</Th>
                    </>
                  ) : (
                    <>
                      <Th>Permissões</Th>
                      <Th>Usuários / manutenção</Th>
                    </>
                  )}
                  <Th>Ações</Th>
                </tr>
              </thead>
              <tbody>
                {rows.map((r) => (
                  <tr key={r.id}>
                    <Td>{r.name}</Td>
                    {"email" in r ? (
                      <>
                        <Td>{r.email}</Td>
                        <Td>
                          {query.data?.profiles.find((p) => p.id === r.profile_id)?.name ??
                            "Sem perfil"}
                        </Td>
                        <Td>
                          <Badge tone={r.active ? "brand" : "neutral"}>
                            {r.active ? "Ativo" : "Inativo"}
                          </Badge>
                        </Td>
                      </>
                    ) : (
                      <>
                        <Td>
                          {Object.entries(permissions)
                            .filter(([key]) => r[key as keyof typeof permissions])
                            .map(([, label]) => label)
                            .join(" · ") || "Somente consulta"}
                        </Td>
                        <Td>{r.system_admin ? "Administrador protegido" : "Personalizável"}</Td>
                      </>
                    )}
                    <Td>
                      <button
                        disabled={pending || ("system_admin" in r && r.system_admin)}
                        className="text-brand underline disabled:opacity-40"
                        onClick={() => {
                          setEditing(r);
                          setError("");
                          setNotice("");
                        }}
                      >
                        Editar
                      </button>
                      {"email" in r && (
                        <button
                          disabled={pending}
                          className="ml-3 text-brand underline disabled:opacity-40"
                          onClick={() => {
                            setResetTarget(r);
                            setGeneratedPassword("");
                            setCopied(false);
                            setEditing(null);
                            setError("");
                            setNotice("");
                          }}
                        >
                          Redefinir senha
                        </button>
                      )}
                    </Td>
                  </tr>
                ))}
                {!rows.length && (
                  <tr>
                    <Td colSpan={5}>Nenhum registro encontrado.</Td>
                  </tr>
                )}
              </tbody>
            </Table>
          </Panel>
          {resetTarget && (
            <Panel title={`Redefinir senha · ${resetTarget.name}`}>
              <div className="space-y-3 p-4">
                <p className="text-sm text-ink2">{resetTarget.email}</p>
                {generatedPassword ? (
                  <>
                    <p role="status" className="text-sm text-up">
                      Senha redefinida com sucesso. Copie antes de fechar.
                    </p>
                    <label className="block text-xs">
                      Nova senha forte
                      <input
                        aria-label="Nova senha forte"
                        className={`${control} font-mono`}
                        readOnly
                        value={generatedPassword}
                        onFocus={(event) => event.target.select()}
                      />
                    </label>
                    <button type="button" className={button} onClick={() => void copyPassword()}>
                      {copied ? "Senha copiada!" : "Copiar senha"}
                    </button>
                  </>
                ) : (
                  <>
                    <p className="text-sm">
                      Uma senha forte de 20 caracteres será gerada. A senha atual será substituída e
                      as sessões deste usuário serão encerradas.
                    </p>
                    <button
                      type="button"
                      className={button}
                      disabled={pending}
                      onClick={() => void resetPassword()}
                    >
                      {pending ? "Redefinindo…" : "Confirmar redefinição"}
                    </button>
                  </>
                )}
                <button
                  type="button"
                  disabled={pending}
                  className="ml-3 text-sm text-ink2"
                  onClick={() => {
                    setResetTarget(null);
                    setGeneratedPassword("");
                    setCopied(false);
                  }}
                >
                  {generatedPassword ? "Fechar" : "Cancelar"}
                </button>
              </div>
            </Panel>
          )}
          {editing && (
            <Panel title={editing === "new" ? "Novo registro" : "Editar registro"}>
              <form
                key={editing === "new" ? "new" : editing.id}
                onSubmit={submit}
                className="space-y-3 p-4"
              >
                <label className="block text-xs">
                  Nome
                  <input
                    name="name"
                    required
                    minLength={2}
                    maxLength={120}
                    defaultValue={editing === "new" ? "" : editing.name}
                    className={control}
                  />
                </label>
                {users ? (
                  <>
                    <label className="block text-xs">
                      E-mail
                      <input
                        name="email"
                        type="email"
                        required
                        maxLength={254}
                        defaultValue={editing !== "new" && "email" in editing ? editing.email : ""}
                        className={control}
                      />
                    </label>
                    <label className="block text-xs">
                      Perfil de acesso
                      <select
                        name="profile_id"
                        required
                        defaultValue={
                          editing !== "new" && "profile_id" in editing
                            ? (editing.profile_id ?? "")
                            : ""
                        }
                        className={control}
                      >
                        <option value="" disabled>
                          Selecione um perfil
                        </option>
                        {query.data?.profiles.map((p) => (
                          <option key={p.id} value={p.id}>
                            {p.name}
                          </option>
                        ))}
                      </select>
                    </label>
                    <label className="block text-xs">
                      {editing === "new"
                        ? "Senha (mínimo de 12 caracteres)"
                        : "Nova senha (opcional)"}
                      <input
                        name="password"
                        type="password"
                        autoComplete="new-password"
                        required={editing === "new"}
                        minLength={12}
                        maxLength={256}
                        className={control}
                      />
                    </label>
                    <label className="flex gap-2 text-sm">
                      <input
                        name="active"
                        type="checkbox"
                        defaultChecked={
                          editing === "new" || ("active" in editing && editing.active)
                        }
                      />
                      Usuário ativo
                    </label>
                  </>
                ) : (
                  <ul className="divide-y divide-line">
                    <li className="py-3"><label><input type="checkbox" name="all_companies" defaultChecked={editing !== "new" && "all_companies" in editing && editing.all_companies} /> Acesso a todas as empresas (inclusive futuras)</label><p className="text-xs">Se desmarcado, somente as empresas selecionadas abaixo serão acessíveis.</p>{query.data?.companies.map(c => <label key={c.id} className="block"><input type="checkbox" name="company_ids" value={c.id} defaultChecked={editing !== "new" && "company_ids" in editing && editing.company_ids.includes(c.id)} /> {c.name}</label>)}</li>
                    {Object.entries(permissions).map(([key, label]) => (
                      <li key={key} className="py-3">
                        <label className="flex items-center justify-between text-sm">
                          {label}
                          <input
                            type="checkbox"
                            name={key}
                            defaultChecked={
                              editing !== "new" &&
                              "system_admin" in editing &&
                              !!editing[key as keyof typeof permissions]
                            }
                          />
                        </label>
                      </li>
                    ))}
                  </ul>
                )}
                <div className="flex gap-2">
                  <button className={button} disabled={pending}>
                    {pending ? "Salvando…" : "Salvar"}
                  </button>
                  <button
                    type="button"
                    disabled={pending}
                    className="text-sm text-ink2"
                    onClick={() => setEditing(null)}
                  >
                    Cancelar
                  </button>
                </div>
              </form>
            </Panel>
          )}
        </>
      )}
    </div>
  );
}

import type { ReactNode } from "react";
import { CashShell } from "./cash-shell";
import { useCompanies } from "./company-context";

export function AppShell({children}:{children:ReactNode}) {
 const {user}=useCompanies();
 return <CashShell user={user}>{children}</CashShell>;
}

import { useCompanies } from "./company-context";
import { CompanySwitcher } from "./company-switcher";
import { Link, useRouterState } from "@tanstack/react-router";
import { useState, type ReactNode } from "react";
import { LockKeyhole, Menu, X, SlidersHorizontal } from "lucide-react";
import { SignOutButton } from "./sign-out-button";
import { CurrencyRateTicker } from "./currency-rate-ticker";
import { isModuleAvailable } from "@/lib/module-availability";
const groups = [
  {
    label: "Operations",
    items: ["Dashboard", "Invoices & AR", "Bills & AP", "Inventory Catalog", "Projects & Margin"],
  },
  { label: "General Ledger", items: ["Journal Entries", "Chart of Accounts", "Trial Balance"] },
  {
    label: "Financial Statements",
    items: [
      "Income Statement (P&L)",
      "Balance Sheet",
      "Cash Flow & Forecast",
      "Sales Tax Summary",
      "AR Aging Position",
    ],
  },
  {
    label: "Banking & Governance",
    items: ["Bank Feeds & Staging"],
  },
  {
    label: "Configurações",
    items: ["Empresas", "Perfis de acesso", "Usuários"],
  },
  {
    label: "Auditoria",
    items: ["Logs de ações"],
  },
  {
    label: "System Parameters",
    items: [
      "Modules Overview",
      "Currencies & FX Rates",
      "Tax Jurisdictions",
      "Payment Terms",
      "Cost Centers",
      "Expense Categories",
      "Fiscal Periods",
    ],
  },
];
const menuRoutes: Record<string, string> = {
  "Dashboard":"/dashboard", "Invoices & AR":"/invoices", "Bills & AP":"/payables", "Inventory Catalog":"/inventory", "Projects & Margin":"/projects", "Journal Entries":"/journals", "Chart of Accounts":"/accounts", "Trial Balance":"/trial-balance", "Income Statement (P&L)":"/dre", "Balance Sheet":"/balance-sheet", "Sales Tax Summary":"/taxes", "AR Aging Position":"/receivables", "Bank Feeds & Staging":"/statements", "Empresas":"/companies", "Modules Overview":"/parameters", "Currencies & FX Rates":"/parameters/currencies", "Tax Jurisdictions":"/parameters/tax-jurisdictions", "Payment Terms":"/parameters/payment-terms", "Cost Centers":"/parameters/cost-centers", "Expense Categories":"/parameters/expense-categories", "Fiscal Periods":"/parameters/fiscal-periods",
  "Cash Flow & Forecast": "/cash-flow",
  "Perfis de acesso": "/access",
  Usuários: "/users",
  "Logs de ações": "/audit-log",
};
export function CashShell({
  children,
  user,
}: {
  children: ReactNode;
  user: { name: string; email: string };
}) {
  const {permissions,activeCompany}=useCompanies();
  const [open, setOpen] = useState(false);
  const path = useRouterState({ select: (s) => s.location.pathname });
  const initials = user.name
    .split(/\s+/)
    .slice(0, 2)
    .map((n) => n[0])
    .join("")
    .toUpperCase();
  const branding = (
    <div className="flex h-14 shrink-0 items-center gap-2.5 border-b border-line/70 px-4">
      <img
        src="/logo-interna.png"
        alt="Quantum Tecnologia"
        className="size-7 rounded-md object-contain shrink-0"
      />
      <div className="leading-tight">
        <p className="text-[13px] font-semibold tracking-tight">Quantum Tecnologia</p>
        <p className="text-[10px] uppercase tracking-[0.14em] text-ink3">US GAAP Multi-Tenant</p>
      </div>
    </div>
  );
  const navigation = (
    <>
      <nav
        aria-label="Módulos"
        className="min-h-0 flex-1 overflow-y-auto px-2.5 py-2.5 [scrollbar-width:none] [&::-webkit-scrollbar]:hidden overscroll-contain"
      >
        {groups.map((g) => (
          <div
            key={g.label}
            className={
              g.label === "System Parameters"
                ? "mb-2.5 rounded-lg border border-line/50 bg-ink/[0.015] p-1"
                : "mb-2"
            }
          >
            <p className="flex items-center gap-1.5 px-2 pb-1 pt-2 text-[10px] font-semibold uppercase tracking-[0.14em] text-ink3">
              {g.label === "System Parameters" && (
                <SlidersHorizontal className="size-3.5 text-brand" />
              )}
              {g.label}
            </p>
            {g.items.filter(label=>label!=="Usuários"||permissions.manage_users).filter(label=>label!=="Perfis de acesso"||permissions.manage_profiles).filter(label=>label!=="Logs de ações"||permissions.view_audit).map((label) =>
              menuRoutes[label] && isModuleAvailable(menuRoutes[label]) ? (
                <Link
                  key={label}
                  to={menuRoutes[label]}
                  activeOptions={{ exact: true }}
                  activeProps={{
                    className:
                      "mt-0.5 flex items-center gap-2 rounded-md bg-white/90 px-2.5 py-1.5 text-[12.5px] font-semibold text-ink ring-1 ring-line shadow-2xs",
                  }}
                  onClick={() => setOpen(false)}
                  className="mt-0.5 flex items-center gap-2 rounded-md px-2.5 py-1.5 text-[12.5px] text-ink2 transition-colors hover:bg-white/60 hover:text-ink"
                >
                  <span
                    className={`size-1.5 rounded-full ${path === menuRoutes[label] ? "bg-brand" : "bg-line"}`}
                  />
                  {label}
                </Link>
              ) : (
                <button
                  key={label}
                  type="button"
                  disabled
                  aria-disabled="true"
                  title="Módulo indisponível nesta etapa"
                  className="mt-0.5 flex w-full cursor-not-allowed items-center gap-2 rounded-md px-2.5 py-1.5 text-left text-[12.5px] text-ink3 opacity-50"
                >
                  <LockKeyhole className="size-3 shrink-0" />
                  {label}
                </button>
              ),
            )}
          </div>
        ))}
      </nav>
      <footer className="shrink-0 border-t border-line/70 p-3 space-y-3">
        <div className="flex min-w-0 items-center gap-2.5">
          <div
            className="grid size-9 shrink-0 place-items-center rounded-lg bg-brand/10 text-xs font-semibold text-brand"
            aria-hidden="true"
          >
            {initials}
          </div>
          <div className="min-w-0 leading-tight">
            <p className="truncate text-[12px] font-semibold text-ink" title={user.name}>
              {user.name}
            </p>
            <p className="mt-1 truncate text-[11px] text-ink3" title={user.email}>
              {user.email}
            </p>
          </div>
        </div>
        <SignOutButton />
      </footer>
    </>
  );
  return (
    <div className="flex min-h-screen w-full bg-canvas text-ink">
      <aside className="sticky top-0 hidden h-screen w-64 shrink-0 flex-col border-r border-line/80 frost-bar md:flex">
        {branding}
        {navigation}
      </aside>
      {open && (
        <div className="fixed inset-0 z-50 flex md:hidden">
          <button
            aria-label="Fechar menu"
            onClick={() => setOpen(false)}
            className="fixed inset-0 bg-ink/40 backdrop-blur-xs"
          />
          <div className="relative z-10 flex h-full w-72 max-w-[85vw] flex-col border-r border-line bg-canvas shadow-2xl">
            {branding}
            <button
              aria-label="Fechar menu"
              onClick={() => setOpen(false)}
              className="absolute right-2 top-4"
            >
              <X className="size-5" />
            </button>
            {navigation}
          </div>
        </div>
      )}
      <div className="flex min-w-0 max-w-full flex-1 flex-col overflow-x-hidden pt-14">
        <header className="fixed top-0 left-0 right-0 md:left-64 z-20 flex h-14 items-center justify-between gap-2 border-b border-line/70 frost-bar px-3 sm:px-6">
          <div className="flex items-center gap-2 sm:gap-3 min-w-0">
            <button
              type="button"
              onClick={() => setOpen(true)}
              className="inline-flex md:hidden items-center justify-center size-8.5 rounded-lg border border-line bg-white/80 text-ink hover:text-brand hover:bg-white transition-colors cursor-pointer shadow-2xs shrink-0"
              aria-label="Abrir menu de navegação"
            >
              <Menu className="size-4.5" />
            </button>
            <div className="flex md:hidden items-center gap-1.5 shrink-0">
              <img
                src="/logo-interna.png"
                alt="Quantum"
                className="size-6 rounded-md object-contain shrink-0"
              />
            </div>
            <div className="hidden sm:flex items-center gap-2 text-[12px] sm:text-[12.5px] text-ink3 truncate min-w-0">
              <span className="hidden lg:inline">Workspace</span>
              <span className="hidden lg:inline text-line">/</span>
              <span className="font-medium text-ink truncate">
                {path === "/cash-flow"
                  ? "Cash Flow & Forecast"
                  : path === "/access"
                    ? "Configurações · Perfis de acesso"
                    : path === "/audit-log"
                      ? "Auditoria · Logs de ações"
                      : path === "/users"
                        ? "Configurações · Usuários"
                        : "Workspace"}
              </span>
            </div>
          </div>
          <div className="flex items-center gap-1.5 sm:gap-2.5 shrink-0">
            <CompanySwitcher />
            <CurrencyRateTicker baseCurrency="USD" />
          </div>
        </header>
        <main className="p-3.5 sm:p-5 md:p-6 flex-1 max-w-full overflow-x-hidden">{children}</main>
        <footer className="border-t border-line/60 px-3.5 sm:px-6 py-3 text-[11px] text-ink3 flex flex-col sm:flex-row items-center justify-between gap-2 bg-canvas/80 text-center sm:text-left">
          <span>
            US GAAP Financial Platform · Client Workspace:{" "}
            <span className="font-medium text-ink">{activeCompany?.name ?? user.name}</span>
          </span>
          <span>
            Notice: Accounting and tax reports are for internal management review prior to CPA
            sign-off.
          </span>
        </footer>
      </div>
    </div>
  );
}

fix.text:
= {
 companies: Company[];
 activeCompany: Company | null;
 selectCompany: (id: string) => void;
 permissions: Permissions;
 user: { id: string; name: string; email: string };
 refresh: () => Promise<unknown>;

if (query.isPending)
   return (
     <p className="p-6" role="status">
       Carregando empresas…
     </p>
   )

if (query.isError)
  return (
    <div className="p-6" role="alert">
      Não foi possível carregar as empresas. Verifique as migrações 004 e 005.{" "}
      <button onClick={() => void query.refetch()}>Tentar novamente</button>
    </div>
  )

