import { z } from "zod";

export const US_STATES = "AL AK AZ AR CA CO CT DE FL GA HI ID IL IN IA KS KY LA ME MD MA MI MN MS MO MT NE NV NH NJ NM NY NC ND OH OK OR PA RI SC SD TN TX UT VT VA WA WV WI WY DC AS GU MP PR VI".split(" ");
export const companySchema = z.object({
  id: z.string().uuid().optional(),
  name: z.string().trim().min(2).max(200),
  tradeName: z.string().trim().max(200).default(""),
  entity: z.enum(["LLC", "Corporation", "Partnership", "Sole Proprietorship", "Nonprofit"]),
  federalTaxClassification: z.enum(["Unspecified", "Disregarded Entity", "Partnership", "C Corporation", "S Corporation", "Tax Exempt"]).default("Unspecified"),
  state: z.string().refine((s) => US_STATES.includes(s), "Estado inválido"),
  ein: z.string().trim().regex(/^(?:\d{2}-?\d{7})?$/, "EIN deve conter nove dígitos").transform((s) => s.replace(/-/g, "")).default(""),
  address: z.string().trim().max(300).default(""),
  city: z.string().trim().max(120).default(""),
  addressState: z.string().refine((s) => !s || US_STATES.includes(s)).default(""),
  zip: z.string().regex(/^(?:\d{5}(?:-\d{4})?)?$/).default(""),
  phone: z.string().trim().max(40).default(""),
  email: z.union([z.literal(""), z.string().email().max(254)]).default(""),
  basis: z.enum(["Accrual", "Cash"]).default("Accrual"),
  fiscalYearEndMonth: z.number().int().min(1).max(12).default(12),
  active: z.boolean().default(true),
});
export type Company = z.infer<typeof companySchema> & { id: string; baseCurrency: "USD"; initials: string; costMethod: "FIFO" | "WeightedAverage"; isPeriodClosed: boolean; activePeriod: string };
export const formatEin = (ein: string) => ein ? `${ein.slice(0, 2)}-${ein.slice(2)}` : "EIN não informado";

import { dateSchema } from "./cash-flow-model";
export function parseStatementCsv(content: string) {
  if (!content || content.length > 2_000_000) throw new Error("Selecione um CSV de até 2 MB.");
  const rows: string[][] = []; let row: string[] = []; let value = ""; let quoted = false;
  const source = content.replace(/^\uFEFF/, "");
  for (let i = 0; i < source.length; i++) {
    const c = source[i];
    if (c === '"') {
      if (quoted && source[i+1] === '"') { value += '"'; i++; }
      else if (!quoted && value) throw new Error("Aspas inválidas no CSV.");
      else quoted = !quoted;
    } else if (c === ',' && !quoted) { row.push(value); value = ""; }
    else if ((c === '\n' || c === '\r') && !quoted) {
      if (c === '\r' && source[i+1] === '\n') i++;
      row.push(value); if (row.some(v => v.trim())) rows.push(row); row = []; value = "";
    } else value += c;
  }
  if (quoted) throw new Error("Aspas não fechadas no CSV.");
  row.push(value); if (row.some(v => v.trim())) rows.push(row);
  const header = rows.shift()?.map(v => v.trim().toLowerCase());
  if (!header || header.join(',') !== 'date,description,amount') throw new Error("Use o cabeçalho date,description,amount. Datas YYYY-MM-DD; valores negativos para saídas.");
  if (!rows.length || rows.length > 5000) throw new Error("O CSV deve conter de 1 a 5.000 transações.");
  return rows.map((r,i) => {
    const amount = Number(r[2]);
    if (r.length !== 3 || !dateSchema.safeParse(r[0]).success || !r[1]?.trim() || r[1].length > 500 || !/^-?\d+(\.\d{1,2})?$/.test(r[2] ?? '') || !Number.isFinite(amount) || amount === 0 || Math.abs(amount) > 999999999999) throw new Error(`Linha ${i+2} inválida.`);
    return {date:r[0]!,description:r[1]!.trim(),amount};
  });
}

